/* SIZZLE production bundle: gzip payload + native DecompressionStream. */(()=>{const P="";try{const b=atob(P),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);if(!("DecompressionStream" in window))throw new Error("DecompressionStream unavailable");new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream("gzip"))).text().then((code)=>{(0,eval)(code);}).catch((e)=>{window.__SIZZLE_BOOT_ERROR__=e;const el=document.getElementById("boot");if(el)el.textContent="启动失败："+e.message;console.error("[sizzle] boot",e);});}catch(e){window.__SIZZLE_BOOT_ERROR__=e;console.error("[sizzle] boot",e);}})();